<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
requireAdmin();
$pdo=getDatabaseConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!validCsrfToken($_POST['csrf_token']??null))$error='Your session expired.';
    else{
        $action=(string)($_POST['action']??'');$id=filter_input(INPUT_POST,'department_id',FILTER_VALIDATE_INT);$name=trim((string)($_POST['department_name']??''));$description=trim((string)($_POST['description']??''));
        if(!in_array($action,['add','update','assign'],true))$error='Invalid action.';
        elseif($action==='assign'){$buildingId=filter_input(INPUT_POST,'building_id',FILTER_VALIDATE_INT);$departmentId=filter_input(INPUT_POST,'assigned_department_id',FILTER_VALIDATE_INT)?:null;if(!$buildingId)$error='Select a valid building.';else{$update=$pdo->prepare('UPDATE buildings SET department_id=:department_id WHERE building_id=:building_id');$update->execute(['department_id'=>$departmentId,'building_id'=>$buildingId]);$message='Building assignment updated.';}}
        elseif($name==='')$error='Department name is required.';
        else{try{if($action==='add'){$statement=$pdo->prepare('INSERT INTO departments(department_name,description) VALUES(:name,:description)');$statement->execute(['name'=>$name,'description'=>$description?:null]);}elseif($id){$statement=$pdo->prepare('UPDATE departments SET department_name=:name,description=:description WHERE department_id=:id');$statement->execute(['name'=>$name,'description'=>$description?:null,'id'=>$id]);}$message='Department saved successfully.';}catch(PDOException $exception){$error=$exception->getCode()==='23000'?'This department already exists.':'Department could not be saved.';}}
    }
}
$departments=$pdo->query('SELECT * FROM departments ORDER BY department_name')->fetchAll();$buildings=$pdo->query('SELECT b.*,d.department_name FROM buildings b LEFT JOIN departments d ON d.department_id=b.department_id ORDER BY b.building_name')->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Departments</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand brand-with-mark" href="../dashboard.php"><span class="brand-mark">LU</span>Liwa University Lost & Found</a><nav><a href="catalog.php">Buildings & Categories</a><a href="manage_users.php">Users</a><a href="../dashboard.php">Dashboard</a></nav></header><main class="admin-page"><p class="eyebrow">University structure</p><h1>Departments</h1><p class="form-intro">Add departments and associate campus buildings with them.</p><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><div class="management-grid"><section class="management-card"><h2>Manage Departments</h2><form class="add-data-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="add"><label>Department name<input name="department_name" required></label><label>Description<input name="description"></label><button class="button button-primary">Add Department</button></form><div class="editable-list"><?php foreach($departments as $department):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="department_id" value="<?=(int)$department['department_id']?>"><input name="department_name" value="<?=e($department['department_name'])?>" required><input name="description" value="<?=e((string)$department['description'])?>"><button>Update</button></form><?php endforeach;?></div></section><section class="management-card"><h2>Assign Buildings</h2><div class="editable-list building-assignments"><?php foreach($buildings as $building):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="building_id" value="<?=(int)$building['building_id']?>"><strong><?=e($building['building_name'])?></strong><select name="assigned_department_id"><option value="">No department</option><?php foreach($departments as $department):?><option value="<?=(int)$department['department_id']?>" <?=(int)$building['department_id']===(int)$department['department_id']?'selected':''?>><?=e($department['department_name'])?></option><?php endforeach;?></select><button>Assign</button></form><?php endforeach;?></div></section></div></main></body></html>
